  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 1, 'Interpretar aceleração como variação da velocidade', 'Interpretar aceleração média como variação de velocidade por intervalo de tempo, com sinal e unidade coerentes. A explicação usa dados explícitos e distingue o modelo físico de conclusões que os dados não autorizam.', '## Aceleração mede mudança de velocidade
A aceleração média é **a = (v final − v inicial) ÷ intervalo de tempo**. Se a velocidade muda de 4 m/s para 10 m/s em 3 s, a variação é 6 m/s e a aceleração média é 2 m/s².

## O sinal depende do eixo
Uma aceleração negativa indica variação no sentido negativo do eixo escolhido. Ela não significa sempre que o objeto está ficando mais lento: se velocidade e aceleração têm o mesmo sentido, o módulo da velocidade aumenta; se têm sentidos opostos, diminui.

## Unidade e interpretação
Dividir m/s por s resulta em m/s². A aceleração média resume o intervalo; ela não diz que a aceleração foi constante em cada instante. Compare início, fim e duração antes de interpretar.',
    'Um carrinho passa de 2 m/s para 8 m/s em 3 s: Δv = 6 m/s; a = 6/3 = 2 m/s². Se passa de 8 m/s para 2 m/s no mesmo intervalo, a = −2 m/s² no eixo positivo escolhido.', array['Anote dados e unidades antes de calcular.', 'Declare o referencial ou o eixo adotado.', 'Mostre a relação usada e confira se a conclusão responde ao enunciado.']::text[], 28, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-physics-interpret-acceleration-sequence","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Ler tabelas de valores.","Calcular diferenças e razões simples."],"key_concepts":["variação da velocidade","intervalo de tempo","aceleração média","sinal","m/s²"],"progression":[{"stage":"DIAGNOSTIC","focus":"Verificar ideias iniciais e leitura das grandezas.","questionIds":["v5-physics-acceleration-01","v5-physics-acceleration-02","v5-physics-acceleration-03","v5-physics-acceleration-04"]},{"stage":"PRACTICE","focus":"Aplicar o critério com apoio gradual.","questionIds":["v5-physics-acceleration-05","v5-physics-acceleration-06","v5-physics-acceleration-07","v5-physics-acceleration-08","v5-physics-acceleration-09","v5-physics-acceleration-10","v5-physics-acceleration-11","v5-physics-acceleration-12","v5-physics-acceleration-13","v5-physics-acceleration-14","v5-physics-acceleration-15","v5-physics-acceleration-16"]},{"stage":"TRANSFER","focus":"Interpretar dados em contextos e justificar a escolha do modelo.","questionIds":["v5-physics-acceleration-17","v5-physics-acceleration-18","v5-physics-acceleration-19","v5-physics-acceleration-20","v5-physics-acceleration-21","v5-physics-acceleration-22","v5-physics-acceleration-23","v5-physics-acceleration-24"]},{"stage":"CONSOLIDATION","focus":"Localizar e corrigir erros de raciocínio.","questionIds":["v5-physics-acceleration-25","v5-physics-acceleration-26","v5-physics-acceleration-27","v5-physics-acceleration-28","v5-physics-acceleration-29","v5-physics-acceleration-30"]},{"stage":"REVIEW","focus":"Retomar conceitos com dados e representações variadas.","questionIds":["v5-physics-acceleration-31","v5-physics-acceleration-32","v5-physics-acceleration-33","v5-physics-acceleration-34","v5-physics-acceleration-35","v5-physics-acceleration-36","v5-physics-acceleration-37","v5-physics-acceleration-38","v5-physics-acceleration-39","v5-physics-acceleration-40"]}],"micro_explanations":[{"trigger":"DELTA_V_FIRST","text":"Subtraia a velocidade inicial da final antes de dividir pelo tempo."},{"trigger":"UNIT_ACCELERATION","text":"Uma unidade de m/s dividida por segundo resulta em m/s²."},{"trigger":"SIGN_IS_DIRECTION","text":"O sinal informa a orientação da variação em relação ao eixo escolhido."},{"trigger":"NEGATIVE_NOT_ALWAYS_SLOWER","text":"Aceleração negativa só significa redução da rapidez se a velocidade aponta no sentido positivo."},{"trigger":"AVERAGE_INTERVAL","text":"A aceleração média resume o intervalo; não prova que a aceleração instantânea foi constante."},{"trigger":"CHECK_MAGNITUDE","text":"Confira se a variação por segundo é compatível com os dados e com o intervalo."}],"remediations":[{"id":"USE_INITIAL_FINAL","misconception":"Trocar variação por velocidade final.","prompt":"Monte uma linha com inicial, final e diferença; calcule final − inicial antes de qualquer divisão."},{"id":"DIVIDE_BY_TIME","misconception":"Esquecer o intervalo de tempo.","prompt":"Depois de achar Δv, divida pelo número de segundos e escreva m/s²."},{"id":"INTERPRET_SIGN","misconception":"Tratar sinal negativo como “sempre desacelera”.","prompt":"Desenhe o eixo e compare o sentido da velocidade ao da aceleração; rapidez depende dessa relação."},{"id":"KEEP_UNITS","misconception":"Misturar km/h com m/s.","prompt":"Converta todas as velocidades para a mesma unidade antes de calcular."},{"id":"MEAN_VS_INSTANT","misconception":"Afirmar aceleração constante a partir de uma média.","prompt":"Limite a conclusão ao intervalo e aos dados fornecidos."},{"id":"RECHECK_SUBTRACTION","misconception":"Inverter a ordem da diferença.","prompt":"Siga a convenção final menos inicial e mantenha o sinal até interpretar o resultado."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"publisher":"TecEscola","title":"Conjunto de medidas e situações de movimento sintéticas","license":"Dados, enunciados e explicações autorais; cenários hipotéticos, sem alegação de fonte oficial."}],"copyright_note":"Questões, valores, explicações e atividade são autorais e sintéticos. Revisão pedagógica pendente; alinhamento oficial não reivindicado.","authentic_activities":[{"id":"v5-physics-interpret-acceleration-motion-audit","title":"Auditoria de registros: interpretar aceleração como variação da velocidade","objective":"Interpretar aceleração média como variação de velocidade por intervalo de tempo, com sinal e unidade coerentes.","context":"Use tabelas sintéticas elaboradas para a atividade, com medidas fictícias e unidades explícitas.","materials":["Tabela de dados sintéticos","Papel quadriculado ou planilha acessível","Calculadora opcional"],"instructions":"Em pares, organize os dados, identifique o referencial ou eixo, calcule as grandezas solicitadas e escreva uma conclusão limitada às evidências. Em seguida, confira um cálculo de outro grupo e explique eventual divergência.","evidence":"Registro reproduzível dos dados, operações com unidades e justificativa baseada nas medidas fornecidas.","privacyGuard":"Utilize apenas dados sintéticos. Não registrar trajetos, velocidade, rotina ou localização de estudantes.","rubric":[{"criterion":"Leitura dos dados","emerging":"Troca valores, unidades ou intervalos.","developing":"Organiza os dados com uma orientação.","proficient":"Organiza todos os pares e unidades corretamente."},{"criterion":"Modelo e cálculo","emerging":"Escolhe operação sem relacioná-la aos dados.","developing":"Aplica a relação correta com apoio.","proficient":"Justifica o modelo e calcula com sinais e unidades coerentes."},{"criterion":"Conclusão","emerging":"Afirma algo não sustentado pelo registro.","developing":"Conclui a partir de parte dos dados.","proficient":"Explica a conclusão e seus limites usando as evidências."}]}],"source_question_feedback":[{"questionId":"v3-physics-physics_average_speed-11","hint":"Calcule primeiro a variação da velocidade (final menos inicial) e só então divida pelo tempo.","errorFocus":"PHYSICS_INTERPRET_ACCELERATION"}],"objective":"Interpretar aceleração média como variação de velocidade por intervalo de tempo, com sinal e unidade coerentes.","common_mistake":"Ignorar o referencial, inverter a variação, misturar unidades ou concluir mais do que os dados mostram.","estimated_minutes":28}'::jsonb
